<?php
defined('ABSPATH')||exit;
class EAIW_Usage{
 public static function record($provider,$model,$prompt=0,$completion=0,$job_id=0){global $wpdb;$t=$wpdb->prefix.'eaiw_usage';$table=$wpdb->prefix.'eaiw_usage'; if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$table))!==$table)return; $p=max(0,(int)$prompt);$c=max(0,(int)$completion);$rates=get_option('eaiw_usage_rates',['openai'=>0.00000015,'gapgpt'=>0.00000015,'gemini'=>0.00000008,'claude'=>0.000003]);$rate=(float)($rates[$provider]??0);$wpdb->insert($t,['provider'=>sanitize_key($provider),'model'=>sanitize_text_field($model),'prompt_tokens'=>$p,'completion_tokens'=>$c,'total_tokens'=>$p+$c,'estimated_cost'=>round(($p+$c)*$rate,8),'job_id'=>(int)$job_id]);}
 public static function summary(){global $wpdb;$t=$wpdb->prefix.'eaiw_usage';$empty=['requests'=>0,'tokens'=>0,'cost'=>0,'providers'=>[]];if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$t))!==$t)return $empty;$empty['requests']=(int)$wpdb->get_var("SELECT COUNT(*) FROM $t");$empty['tokens']=(int)$wpdb->get_var("SELECT COALESCE(SUM(total_tokens),0) FROM $t");$empty['cost']=(float)$wpdb->get_var("SELECT COALESCE(SUM(estimated_cost),0) FROM $t");$empty['providers']=$wpdb->get_results("SELECT provider,COUNT(*) requests,SUM(total_tokens) tokens,SUM(estimated_cost) cost FROM $t GROUP BY provider ORDER BY requests DESC",ARRAY_A);return $empty;}
}
